            and load == 0
            and position in access
            and isinstance(tile, dict)
            and int(tile.get("yield_units", 0) or 0) > 0
        ):
            replacement = ["HARVEST"]
        if replacement is not None:
            unit_actions[index] = replacement

    action["farmer"] = unit_actions[0]
    action["hands"] = unit_actions[1:]
    return action


def apply_overlay(obs, base_action, mode):
    """Apply one named ablation without changing the wrapped base policy."""
    step = max(0, int(obs.get("step", 0) or 0))
    action = align_hands(base_action, obs)
    if mode in {"terminal_existing", "terminal_value", "terminal_collision"}:
        action = monetizable_terminal_units(obs, action, step)
    if step == 718:
        if mode in {"c20_append", "terminal_existing"}:
            action = terminal_market(obs, action, "existing", replace=False)
        elif mode == "terminal_value":
            action = terminal_market(obs, action, "value", replace=True)
        elif mode == "terminal_collision":
            action = terminal_market(obs, action, "collision", replace=True)
        elif mode in {"late_collision", "late_clone_collision"}:
            # Final-turn purchases and hires cannot improve bank reward.  At
            # the last executable market step, replace them with every
            # projected sellable unit, including same-turn DROP/PLACE stock.
            action = terminal_market(obs, action, "collision", replace=True)
    elif mode == "late_collision" and step >= 680:
        action = terminal_market(obs, action, "collision", replace=False)
    elif mode == "late_clone_collision" and step >= 680 and clone_distance(obs) <= 2:
        action = terminal_market(obs, action, "collision", replace=False)
    return action


def wrap_policy(policy, mode):
    def wrapped(obs):
        return apply_overlay(obs, policy(obs), mode)

    return wrapped

scripts.v22_market_impact:
#!/usr/bin/env python3
"""Order-safe market-impact controls for the v22 Kaggriculture study.

The public v21.1 agent ranks a predicted collision with a hand-written
exposure score and then moves those SELL orders to the front of the complete
market queue.  This module provides deliberately smaller counterfactuals:

* ``impact_slots`` changes only the contents of existing SELL slots;
* ``impact_front`` uses the same score but moves all SELLs before non-SELLs;
* neither mode creates, removes, or changes the quantity of an order.

The default price curve below is an exact, stdlib-only transcription of the
official Kaggriculture 1.32.7 market parameters.  Keeping it local also makes
the eventual submission artifact independent of ``kaggle_environments``.
"""

from __future__ import annotations

import copy
import math


PRICE_FLOOR = 1
MARKET_PARAMS = {
    "WHEAT": (25, 10000, 400, "sqrt", 0.8, "log", 0.2),
    "CARROT": (35, 10000, 450, "hinge", 1.0, "sqrt", 0.7),
    "TOMATO": (60, 10000, 200, "hinge", 0.4, "sqrt", 0.6),
    "STRAWBERRY": (120, 10000, 100, "sqrt", 0.7, "linear", 1.6),
    "MELON": (250, 10000, 300, "log", 0.2, "sq", 3.6),
    "EGG": (50, 10000, 332, "hinge", 0.4, "log", 0.2),
    "MILK": (160, 10000, 122, "sqrt", 0.6, "linear", 1.6),
    "WOOL": (200, 10000, 105, "log", 0.2, "sq", 3.2),
    "FERTILIZER": (100, 10000, 200, "linear", 0.4, "linear", 0.4),
}


def _get(value, key, default=None):
    if isinstance(value, dict):
        return value.get(key, default)
    return getattr(value, key, default)


def _shape(name: str, value: float, scale: float | None = None) -> float:
    value = max(0.0, float(value))
    if name == "linear":
        return value
    if name == "sq":
        return value * value
    if name == "sqrt":
        return math.sqrt(value)
    if name == "log":
        return math.log1p(value)
    if name == "log10":
        return math.log10(1.0 + value)
    if name == "hinge":
        if scale is None or scale <= 0:
            return value
        normalized = value / scale
        return normalized + 8.0 * max(0.0, normalized - 1.0) ** 2
    raise ValueError(f"unknown market shape {name!r}")


def market_price(item: str, inventory: int) -> int:
    """Return the Kaggriculture 1.32.7 default quote for one inventory level."""
    base, equilibrium, scale, below_func, below_target, above_func, above_target = (
        MARKET_PARAMS[item]
    )
    if inventory < equilibrium:
        amplitude = below_target * base / _shape(below_func, scale, scale)
        price = base + amplitude * _shape(
            below_func, equilibrium - inventory, scale
        )
    else:
        amplitude = above_target * base / _shape(above_func, scale, scale)
        price = base - amplitude * _shape(
            above_func, inventory - equilibrium, scale
        )
    return max(PRICE_FLOOR, int(round(price)))


def is_sell(order) -> bool:
    return (
        isinstance(order, (list, tuple))
        and len(order) >= 3
        and order[0] == "SELL"
        and order[1] in MARKET_PARAMS
    )


def impact_score(obs, order) -> float:
    """Proxy for the price damage caused by executing this SELL now.

    This intentionally follows the public impact-ranking experiment:
    quantity * (current quote - quote after this order).  It estimates the
    value of being earlier without pretending to observe the opponent's
    private inventory or simultaneous action.
    """
    if not is_sell(order):
        return float("-inf")
    item = str(order[1])
    try:
        quantity = max(0, int(order[2]))
    except (TypeError, ValueError):
        return 0.0
    market = _get(obs, "market", {}) or {}
    inventory = _get(market, "inventory", {}) or {}
    prices = _get(market, "prices", {}) or {}
    current_inventory = int(_get(inventory, item, 10000) or 0)
    current_quote = float(
        _get(prices, item, market_price(item, current_inventory)) or 0
    )
    later_quote = float(market_price(item, current_inventory + quantity))
    return float(quantity) * max(0.0, current_quote - later_quote)


def _safe_action(action):
    result = copy.deepcopy(action) if isinstance(action, dict) else {}
    result.setdefault("farmer", ["PASS"])
    result.setdefault("hands", [])
    market = result.get("market")
    result["market"] = list(market) if isinstance(market, (list, tuple)) else []
    return result


def reorder_market(obs, action, mode: str = "impact_slots"):
    """Reorder existing SELLs while preserving the order multiset exactly."""
    result = _safe_action(action)
    market = list(result["market"])
    sell_rows = [
        (impact_score(obs, order), -index, copy.deepcopy(order))
        for index, order in enumerate(market)
        if is_sell(order)
    ]
    if len(sell_rows) < 2:
        return result
    sell_rows.sort(reverse=True)
    ranked = [row[2] for row in sell_rows]
    if mode == "impact_slots":
        iterator = iter(ranked)
        result["market"] = [next(iterator) if is_sell(order) else order for order in market]
    elif mode == "impact_front":
        others = [order for order in market if not is_sell(order)]
        result["market"] = ranked + others
    else:
        raise ValueError(f"unknown reorder mode {mode!r}")
    return result


def wrap_market_impact(base_policy, mode: str = "impact_slots"):
    telemetry = {"games": 0, "sell_turns": 0, "reordered_turns": 0}

    def policy(obs):
        step = max(0, int(_get(obs, "step", 0) or 0))
        if step == 0:
            telemetry["games"] += 1
        original = _safe_action(base_policy(obs))
        if sum(is_sell(order) for order in original["market"]) >= 2:
            telemetry["sell_turns"] += 1
        result = reorder_market(obs, original, mode)
        telemetry["reordered_turns"] += result["market"] != original["market"]
        return result

    policy.telemetry = telemetry
    return policy

v23.state_encoder:
"""Observation -> compact strategic state for sparse closed-loop decisions."""

from __future__ import annotations

from collections import Counter
from dataclasses import dataclass
from typing import Any


PRODUCTS = (
    "WHEAT",
    "CARROT",
    "TOMATO",
    "STRAWBERRY",
    "MELON",
    "EGG",
    "MILK",
    "WOOL",
    "FERTILIZER",
)
BASE_PRICE = {
    "WHEAT": 25,
    "CARROT": 35,
    "TOMATO": 60,
    "STRAWBERRY": 120,
    "MELON": 250,
    "EGG": 50,
    "MILK": 160,
    "WOOL": 200,
    "FERTILIZER": 100,
}
SHOP_PRODUCTS = {
    "BAKERY": ("EGG", "WHEAT"),
    "PIZZA_SHOP": ("MILK", "TOMATO", "WHEAT"),
    "BRUNCH_SPOT": ("EGG", "WHEAT", "STRAWBERRY"),
    "YARN_STORE": ("WOOL",),
    "ICE_CREAM_SHOP": ("STRAWBERRY", "MILK", "WHEAT"),
    "PET_CAFE": ("CARROT",),
    "SMOOTHIE_SHOP": ("STRAWBERRY", "MILK"),
    "FARMERS_MARKET": ("WHEAT", "CARROT", "TOMATO", "STRAWBERRY"),
}
ANIMAL_PRODUCT = {"COW": "MILK", "SHEEP": "WOOL", "GOOSE": "EGG"}


def get(value: Any, key: str, default=None):
    if isinstance(value, dict):
        return value.get(key, default)
    return getattr(value, key, default)


def regime_from_configuration(configuration: Any) -> str:
    interval = int(get(configuration, "townCenterSellInterval", 12) or 12)
    return "rebalance" if interval >= 24 else "legacy"


def _asset_features(farm: dict) -> dict[str, float]:
    counts = Counter()
    exposure = Counter()
    for row in farm.get("tiles", []) or []:
        for tile in row:
            if not isinstance(tile, dict):
                continue
            kind = tile.get("kind")
            counts[f"kind_{kind}"] += 1
            crop = tile.get("crop")
            animal = tile.get("animal")
            if crop:
                counts[f"crop_{crop}"] += 1
                exposure[crop] += max(1, int(tile.get("yield_units", 0) or 0))
            if animal:
                counts[f"animal_{animal}"] += 1
                product = ANIMAL_PRODUCT.get(animal)
                if product:
                    exposure[product] += max(1, int(tile.get("yield_units", 0) or 0))
            if tile.get("fertilizer_available"):
                exposure["FERTILIZER"] += 1
    return {
        **{name: float(value) for name, value in counts.items()},
        **{f"exposure_{name}": float(value) for name, value in exposure.items()},
        "hands": float(len(farm.get("hands", []) or [])),
        "quadrants": float(len(farm.get("unlocked_quadrants", []) or [])),
        "money": float(farm.get("money", 0) or 0),
    }


def shop_demand_per_day(
    unlocked_shops: list[str],
    *,
    day: int,
    regime: str,
    turns_per_day: int = 24,
    shop_interval: int = 4,
    center_interval: int | None = None,
) -> dict[str, float]:
    """Current per-day demand, counting duplicate shop instances."""
    demand = {product: 0.0 for product in PRODUCTS}
    ticks = turns_per_day / max(1, shop_interval)
    for shop in unlocked_shops:
        products = SHOP_PRODUCTS.get(shop, ())
        multiplier = 2 if len(products) == 1 else 1
        for product in products:
            demand[product] += ticks * multiplier
    if center_interval is None:
        center_interval = 24 if regime == "rebalance" else 12
    center_ticks = turns_per_day / max(1, center_interval)
    center_multiplier = 1 if regime == "rebalance" else (4 if day >= 20 else 2 if day >= 10 else 1)
    for product in PRODUCTS:
        if product != "FERTILIZER":
            demand[product] += center_ticks * center_multiplier
    return demand


@dataclass(frozen=True)
class StrategicState:
    step: int
    day: int
    remaining_turns: int
    player: int
    regime: str
    shops: tuple[str, ...]
    shop_counts: dict[str, int]
    demand_per_day: dict[str, float]
    market_inventory: dict[str, float]
    market_prices: dict[str, float]
    own: dict[str, float]
    opponent: dict[str, float]
    shed: dict[str, float]
    seeds: dict[str, float]

    def flat_features(self) -> dict[str, float]:
        out = {
            "step": float(self.step),
            "day": float(self.day),
            "remaining_turns": float(self.remaining_turns),
            "is_rebalance": float(self.regime == "rebalance"),
            "duplicate_shops": float(len(self.shops) - len(set(self.shops))),
        }
        for shop in SHOP_PRODUCTS:
            out[f"shop_{shop}"] = float(self.shop_counts.get(shop, 0))
        for product in PRODUCTS:
            out[f"demand_{product}"] = float(self.demand_per_day.get(product, 0))
            out[f"inventory_{product}"] = float(self.market_inventory.get(product, 0))
            price = float(self.market_prices.get(product, BASE_PRICE[product]))
            out[f"price_{product}"] = price
            out[f"price_ratio_{product}"] = price / BASE_PRICE[product]
            out[f"shed_{product}"] = float(self.shed.get(product, 0))
            out[f"own_exposure_{product}"] = float(self.own.get(f"exposure_{product}", 0))
            out[f"opp_exposure_{product}"] = float(self.opponent.get(f"exposure_{product}", 0))
        for prefix, values in (("own", self.own), ("opp", self.opponent)):
            for name in ("money", "hands", "quadrants", "kind_WEED"):
                out[f"{prefix}_{name}"] = float(values.get(name, 0))
        return out


def encode_state(obs: Any, configuration: Any = None) -> StrategicState:
    player = int(get(obs, "player", 0) or 0)
    farms = list(get(obs, "farms", []) or [])
    mine = farms[player] if player < len(farms) else {}
    opponent_index = 1 - player if len(farms) == 2 else player
    opponent = farms[opponent_index] if opponent_index < len(farms) else {}
    market = get(obs, "market", {}) or {}
    town = get(obs, "town", {}) or {}
    private = get(obs, "private", {}) or {}
    step = int(get(obs, "step", 0) or 0)
    day = int(get(obs, "day", step // 24) or 0)
    regime = regime_from_configuration(configuration)
    shops = tuple(get(town, "unlocked_shops", []) or [])
    shop_interval = int(get(configuration, "townShopSellInterval", 4) or 4)
    turns_per_day = int(get(configuration, "turnsPerDay", 24) or 24)
    center_interval = int(
        get(configuration, "townCenterSellInterval", 24 if regime == "rebalance" else 12)
        or (24 if regime == "rebalance" else 12)
    )
    return StrategicState(
        step=step,
        day=day,
        remaining_turns=max(0, 719 - step),
        player=player,
        regime=regime,
        shops=shops,
        shop_counts=dict(Counter(shops)),
        demand_per_day=shop_demand_per_day(
            list(shops),
            day=day,
            regime=regime,
            turns_per_day=turns_per_day,
            shop_interval=shop_interval,
            center_interval=center_interval,
        ),
        market_inventory={
            product: float(value)
            for product, value in (get(market, "inventory", {}) or {}).items()
        },
        market_prices={
            product: float(value)
            for product, value in (get(market, "prices", {}) or {}).items()
        },
        own=_asset_features(mine),
        opponent=_asset_features(opponent),
        shed={
            product: float(value)
            for product, value in (get(private, "shed", {}) or {}).items()
        },
        seeds={
            product: float(value)
            for product, value in (get(private, "seeds", {}) or {}).items()
        },
    )

v23.simulator:
"""Small exact market rollout used by the v23 event-triggered planner.

This is intentionally not a full farm simulator.  The actor schedule remains a
validated open-loop backbone; only the market subsystem is rolled forward when
an observed demand or inventory event can change a SELL continuation.
"""

from __future__ import annotations

from dataclasses import dataclass
import math
from typing import Mapping

from v23.state_encoder import PRODUCTS, SHOP_PRODUCTS


PRICE_FLOOR = 1
MARKET_PARAMS = {
    "WHEAT": (25, 10000, 400, "sqrt", 0.80, "log", 0.20),
    "CARROT": (35, 10000, 450, "hinge", 1.00, "sqrt", 0.70),
    "TOMATO": (60, 10000, 200, "hinge", 0.40, "sqrt", 0.60),
    "STRAWBERRY": (120, 10000, 100, "sqrt", 0.70, "linear", 1.60),
    "MELON": (250, 10000, 300, "log", 0.20, "sq", 3.60),
    "EGG": (50, 10000, 332, "hinge", 0.40, "log", 0.20),
    "MILK": (160, 10000, 122, "sqrt", 0.60, "linear", 1.60),
    "WOOL": (200, 10000, 105, "log", 0.20, "sq", 3.20),
    "FERTILIZER": (100, 10000, 200, "linear", 0.40, "linear", 0.40),
}


def _shape(name: str, value: float, scale: float | None = None) -> float:
    value = max(0.0, value)
    if name == "linear":
        return value
    if name == "sq":
        return value * value
    if name == "sqrt":
        return math.sqrt(value)
    if name == "log":
        return math.log1p(value)
    if name == "log10":
        return math.log10(1.0 + value)
    if name == "hinge":
        if scale is None or scale <= 0:
            return value
        normalized = value / scale
        return normalized + 8.0 * max(0.0, normalized - 1.0) ** 2
    raise ValueError(name)


def market_price(item: str, inventory: int) -> int:
    base, equilibrium, scale, below_func, below_target, above_func, above_target = (
        MARKET_PARAMS[item]
    )
    if inventory < equilibrium:
        amplitude = below_target * base / _shape(below_func, scale, scale)
        price = base + amplitude * _shape(
            below_func, equilibrium - inventory, scale
        )
    else:
        amplitude = above_target * base / _shape(above_func, scale, scale)
        price = base - amplitude * _shape(
            above_func, inventory - equilibrium, scale
        )
    return max(PRICE_FLOOR, int(round(price)))


def execute_sell(item: str, inventory: int, quantity: int) -> tuple[int, int]:
    """Exact unit-lockstep revenue for one unilateral SELL order."""
    revenue = 0
    inventory = int(inventory)
    for _ in range(max(0, int(quantity))):
        quote = market_price(item, inventory)
        revenue += quote
        # Official engine does not add $1 sales to market inventory.
        if quote > 1:
            inventory += 1
    return revenue, inventory


def demand_on_tick(unlocked_shops: tuple[str, ...]) -> dict[str, int]:
    demand = {product: 0 for product in PRODUCTS}
    for shop in unlocked_shops:
        products = SHOP_PRODUCTS.get(shop, ())
        multiplier = 2 if len(products) == 1 else 1
        for product in products:
            demand[product] += multiplier
    return demand


@dataclass(frozen=True)
class MarketRollout:
    immediate_revenue: float
    terminal_value: float
    objective: float
    ending_inventory: int
    ending_quantity: int


def rollout_sale_choice(
    *,
    item: str,
    market_inventory: int,
    owned_quantity: int,
    sell_now: int,
    step: int,
    horizon_turns: int,
    unlocked_shops: tuple[str, ...],
    regime: str,
    projected_supply_per_turn: float = 0.0,
    terminal_discount: float = 0.95,
    shop_interval: int = 4,
    center_interval: int | None = None,
) -> MarketRollout:
    """Evaluate immediate sale plus marked-to-market remaining stock.

    Supply is a deliberately coarse public-state projection.  Demand timing and
    the official nonlinear price curve are exact for the fixed shop set.
    """
    center_interval = center_interval or (24 if regime == "rebalance" else 12)
    sell_now = min(max(0, int(sell_now)), max(0, int(owned_quantity)))
    immediate, inventory = execute_sell(item, market_inventory, sell_now)
    remaining = max(0, int(owned_quantity) - sell_now)
    shop_tick = demand_on_tick(unlocked_shops)
    for offset in range(max(0, int(horizon_turns))):
        future_step = int(step) + offset
        inventory += int(round(max(0.0, projected_supply_per_turn)))
        if future_step % max(1, shop_interval) == 0:
            inventory -= shop_tick.get(item, 0)
        if future_step % max(1, center_interval) == 0 and item != "FERTILIZER":
            if regime == "rebalance":
                multiplier = 1
            else:
                day = future_step // 24
                multiplier = 4 if day >= 20 else 2 if day >= 10 else 1
            inventory -= multiplier
    terminal_quote = market_price(item, inventory)
    terminal_value = terminal_discount * remaining * terminal_quote
    return MarketRollout(
        immediate_revenue=float(immediate),
        terminal_value=float(terminal_value),
        objective=float(immediate) + terminal_value,
        ending_inventory=inventory,
        ending_quantity=remaining,
    )


def best_sale_quantity(
    *,
    base_quantity: int,
    switch_cost: float = 0.0,
    **kwargs,
) -> tuple[int, dict[int, MarketRollout]]:
    """Search a bounded quantity set and charge deviation from the backbone."""
    base_quantity = max(0, int(base_quantity))
    candidates = sorted(
        {
            0,
            base_quantity,
            base_quantity // 4,
            base_quantity // 2,
            (3 * base_quantity) // 4,
        }
    )
    rows = {
        quantity: rollout_sale_choice(sell_now=quantity, **kwargs)
        for quantity in candidates
    }
    selected = max(
        candidates,
        key=lambda quantity: (
            rows[quantity].objective
            - (0.0 if quantity == base_quantity else float(switch_cost)),
            -abs(quantity - base_quantity),
        ),
    )
    return selected, rows


def projected_supply_from_exposure(
    own_exposure: Mapping[str, float],
    opponent_exposure: Mapping[str, float],
    item: str,
    horizon_turns: int,
) -> float:
    """Conservative per-turn public supply proxy for the market rollout."""
    total = max(0.0, float(own_exposure.get(item, 0))) + max(
        0.0, float(opponent_exposure.get(item, 0))
    )
    return total / max(24.0, float(horizon_turns))

v23.policy_library:
"""Safe continuation and market experts for v23 research."""

from __future__ import annotations

import copy
from dataclasses import dataclass
from typing import Any, Callable

from scripts.v22_market_impact import impact_score, is_sell
from v23.simulator import best_sale_quantity, market_price
from v23.state_encoder import BASE_PRICE, encode_state, get, regime_from_configuration


PASS = {"farmer": ["PASS"], "hands": [], "market": []}


def safe_action(action: Any) -> dict:
    result = copy.deepcopy(action) if isinstance(action, dict) else {}
    result.setdefault("farmer", ["PASS"])
    result.setdefault("hands", [])
    market = result.get("market")
    result["market"] = list(market) if isinstance(market, (list, tuple)) else []
    return result


def shared_prefix_length(routes: dict[str, list[dict]]) -> int:
    if not routes:
        return 0
    rows = list(routes.values())
    prefix = 0
    for actions in zip(*rows):
        if any(action != actions[0] for action in actions[1:]):
            break
        prefix += 1
    return prefix


def _demand_adjusted_score(obs, configuration, order, alpha: float) -> float:
    score = impact_score(obs, order)
    if score <= 0 or not is_sell(order):
        return score
    state = encode_state(obs, configuration)
    item = str(order[1])
    quantity = max(0, int(order[2]))
    inventory = int(state.market_inventory.get(item, 10000))
    demand = max(0.0, state.demand_per_day.get(item, 0.0))
    post_inventory = inventory + quantity
    excess = max(0.0, post_inventory - 10000)
    recovery_days = excess / max(0.25, demand)
    urgency = min(1.0, recovery_days / 10.0)
    return score * (1.0 + max(0.0, float(alpha)) * urgency)


def reorder_sell_slots(
    obs,
    action,
    configuration=None,
    *,
    demand_alpha: float = 0.0,
) -> dict:
    """Sort only existing SELL slots; preserve every non-SELL position."""
    result = safe_action(action)
    market = list(result["market"])
    sells = []
    for index, order in enumerate(market):
        if not is_sell(order):
            continue
        score = (
            _demand_adjusted_score(obs, configuration, order, demand_alpha)
            if demand_alpha > 0
            else impact_score(obs, order)
        )
        sells.append((score, -index, copy.deepcopy(order)))
    if len(sells) < 2:
        return result
    sells.sort(reverse=True)
    ranked = iter(row[2] for row in sells)
    result["market"] = [next(ranked) if is_sell(order) else order for order in market]
    return result


def plan_sell_quantities(
    obs,
    action,
    configuration=None,
    *,
    horizon_turns: int = 24,
    switch_cost: float = 250.0,
    minimum_step: int = 240,
    cash_reserve: float = 2500.0,
) -> dict:
    """Bounded MPC-like SELL quantity adjustment for rebalance experiments.

    Quantity changes are prohibited on capital-order turns and while cash is
    tight.  This prevents a delayed sale from silently invalidating BUY/HIRE.
    """
    result = safe_action(action)
    if regime_from_configuration(configuration) != "rebalance":
        return result
    step = int(get(obs, "step", 0) or 0)
    if step < minimum_step:
        return result
    market_orders = result["market"]
    if any(order and order[0] != "SELL" for order in market_orders):
        return result
    state = encode_state(obs, configuration)
    if state.own.get("money", 0.0) < cash_reserve:
        return result
    changed = []
    for order in market_orders:
        if not is_sell(order):
            changed.append(order)
            continue
        item = str(order[1])
        base_quantity = max(0, int(order[2]))
        owned = max(base_quantity, int(state.shed.get(item, 0)))
        selected, _rows = best_sale_quantity(
            item=item,
            market_inventory=int(state.market_inventory.get(item, 10000)),
            owned_quantity=owned,
            base_quantity=base_quantity,
            step=step,
            horizon_turns=horizon_turns,
            unlocked_shops=state.shops,
            regime=state.regime,
            switch_cost=switch_cost,
        )
        if selected > 0:
            changed.append(["SELL", item, selected])
    result["market"] = changed
    return result


def terminal_liquidation(obs, action) -> dict:
    result = safe_action(action)
    step = int(get(obs, "step", 0) or 0)
    if step != 718:
        return result
    private = get(obs, "private", {}) or {}
    shed = get(private, "shed", {}) or {}
    market = get(obs, "market", {}) or {}
    inventory = get(market, "inventory", {}) or {}
    rows = []
    for item, quantity in shed.items():
        if item not in BASE_PRICE or int(quantity or 0) <= 0:
            continue
        quote = market_price(item, int(get(inventory, item, 10000) or 10000))
        rows.append((quote * int(quantity), ["SELL", item, int(quantity)]))
    rows.sort(reverse=True)
    result["market"] = [row[1] for row in rows[:10]]
    return result


@dataclass
class RouteLibrary:
    routes: dict[str, list[dict]]
    default: str
    trigger_step: int

    def __post_init__(self):
        if self.default not in self.routes:
            raise ValueError(f"missing default route {self.default!r}")
        if shared_prefix_length(self.routes) < self.trigger_step:
            raise ValueError("routes do not share the required decision prefix")

    def policy(self, selector: Callable[[Any, Any], str]):
        selections = {0: self.default, 1: self.default}
        last_step = {0: -1, 1: -1}

        def agent(obs, configuration=None):
            seat = int(get(obs, "player", 0) or 0)
            step = int(get(obs, "step", 0) or 0)
            if step == 0 or step < last_step[seat]:
                selections[seat] = self.default
            last_step[seat] = step
            if step == self.trigger_step:
                selected = selector(obs, configuration)
                if selected in self.routes:
                    selections[seat] = selected
            route = self.routes[selections[seat]]
            return safe_action(route[min(step, len(route) - 1)])

        agent.selections = selections
        return agent

v24.market_maker:
"""Independent, reserve-safe one-tick market-making expert.

The expert does not change the farm route.  It may add one ``BUY_PRODUCT``
order immediately before deterministic town demand and one matching ``SELL``
order on a later turn.  Entry capital is limited to money left after reserving
the current route's investment orders, emergency feed capital, and a fixed
cash floor.  The bought position is accounted for separately from operational
WHEAT so an exit cannot knowingly consume the route's feed stock.

This module is observation-only at runtime.  The complete route is used only
to reserve already-planned public submission actions and to verify that a
future exit has an available market-order slot.
"""

from __future__ import annotations

import copy
from dataclasses import dataclass
import math
from typing import Any, Iterable

from scripts.v19_terminal import clone_distance
from v23.simulator import execute_sell, market_price
from v23.state_encoder import SHOP_PRODUCTS, get


ANIMAL_COST = {"GOOSE": 300, "COW": 400, "SHEEP": 500}
CROP_COST = {
    "WHEAT": 10,
    "CARROT": 20,
    "TOMATO": 50,
    "STRAWBERRY": 100,
    "MELON": 80,
}
LAND_COST = (1000, 2000, 4000)


@dataclass(frozen=True)
class MarketMakerConfig:
    enabled: bool = True
    item: str = "WHEAT"
    # A non-WHEAT trading expert must still protect operational animal feed.
    feed_item: str = "WHEAT"
    start_step: int = 260
    stop_entry_step: int = 716
    max_batch: int = 60
    minimum_expected_profit: float = 1.0
    mirror_minimum_expected_profit: float = 1.0
    mirror_distance_threshold: float = 2.0
    mirror_streak_required: int = 48
    minimum_cash_reserve: float = 2500.0
    feed_days_reserve: float = 2.0
    investment_horizon: int = 2
    price_cost_buffer: float = 1.05
    shed_headroom: int = 20
    max_hold_steps: int = 4
    max_orders: int = 10
    shed_capacity: int = 100


@dataclass(frozen=True)
class RoundTripPlan:
    quantity: int
    buy_cost: float
    sell_revenue: float
    expected_profit: float
    inventory_after_buy: int
    inventory_before_sell: int


@dataclass(frozen=True)
class ReserveBreakdown:
    money: float
    cash_floor: float
    feed: float
    investment: float
    available: float


def execute_buy(item: str, inventory: int, quantity: int) -> tuple[int, int]:
    """Exact unilateral BUY_PRODUCT cost under official per-unit pricing."""
    cost = 0
    inventory = int(inventory)
    for _ in range(max(0, int(quantity))):
        quote = market_price(item, inventory - 1)
        cost += quote
        inventory -= 1
    return cost, inventory


def round_trip_plan(
    *,
    item: str,
    inventory: int,
    quantity: int,
    intervening_demand: int,
) -> RoundTripPlan:
    """Buy now, apply known town demand, then liquidate on the next turn."""
    quantity = max(0, int(quantity))
    cost, after_buy = execute_buy(item, inventory, quantity)
    before_sell = after_buy - max(0, int(intervening_demand))
    revenue, _ending_inventory = execute_sell(item, before_sell, quantity)
    return RoundTripPlan(
        quantity=quantity,
        buy_cost=float(cost),
        sell_revenue=float(revenue),
        expected_profit=float(revenue - cost),
        inventory_after_buy=after_buy,
        inventory_before_sell=before_sell,
    )


def best_round_trip_quantity(
    *,
    item: str,
    inventory: int,
    intervening_demand: int,
    maximum_quantity: int,
    minimum_expected_profit: float = 1.0,
) -> RoundTripPlan | None:
    """Return the smallest quantity attaining maximum positive one-tick PnL."""
    rows = [
        round_trip_plan(
            item=item,
            inventory=inventory,
            quantity=quantity,
            intervening_demand=intervening_demand,
        )
        for quantity in range(1, max(0, int(maximum_quantity)) + 1)
    ]
    if not rows:
        return None
    selected = max(rows, key=lambda row: (row.expected_profit, -row.quantity))
    return (
        selected
        if selected.expected_profit >= float(minimum_expected_profit)
        else None
    )


def demand_on_step(obs: Any, configuration: Any, item: str) -> int:
    """Exact visible town demand that executes after this turn's market."""
    step = int(get(obs, "step", 0) or 0)
    town = get(obs, "town", {}) or {}
    shops = list(get(town, "unlocked_shops", []) or [])
    shop_interval = max(
        1, int(get(configuration, "townShopSellInterval", 4) or 4)
    )
    center_interval = max(
        1, int(get(configuration, "townCenterSellInterval", 12) or 12)
    )
    turns_per_day = max(1, int(get(configuration, "turnsPerDay", 24) or 24))
    demand = 0
    if step % shop_interval == 0:
        for shop in shops:
            products = SHOP_PRODUCTS.get(str(shop), ())
            if item in products:
                demand += 2 if len(products) == 1 else 1
    if item != "FERTILIZER" and step % center_interval == 0:
        if center_interval >= 24:
            demand += 1
        else:
            day = step // turns_per_day
            demand += 4 if day >= 20 else 2 if day >= 10 else 1
    return demand


def _seat(obs: Any) -> int:
    return 1 if int(get(obs, "player", 0) or 0) == 1 else 0


def _farm(obs: Any) -> dict:
    seat = _seat(obs)
    farms = list(get(obs, "farms", []) or [])
    return farms[seat] if seat < len(farms) else {}


def _safe_action(action: Any) -> dict:
    copied = copy.deepcopy(action) if isinstance(action, dict) else {}
    copied["farmer"] = list(copied.get("farmer") or ["PASS"])
    copied["hands"] = [
        list(order or ["PASS"]) for order in (copied.get("hands") or [])
    ]
    copied["market"] = [list(order) for order in (copied.get("market") or [])]
    return copied


def _animal_count(farm: dict) -> int:
    return sum(
        isinstance(tile, dict) and bool(tile.get("animal"))
        for row in farm.get("tiles", []) or []
        for tile in row
    )


def _shed_access_tiles(board_size: int) -> set[tuple[int, int]]:
    half = max(1, int(board_size)) // 2
    return {
        (half - 1, half - 1),
        (half, half - 1),
        (half - 1, half),
        (half, half),
    }


def _take(inventory: dict[str, int], item: str, quantity: int) -> int:
    taken = min(
        max(0, int(quantity)),
        max(0, int(inventory.get(item, 0) or 0)),
    )
    if taken:
        left = int(inventory.get(item, 0) or 0) - taken
        if left > 0:
            inventory[item] = left
        else:
            inventory.pop(item, None)
    return taken


def _project_private_after_actor(
    obs: Any,
    action: Any,
    *,
    shed_capacity: int,
) -> tuple[dict[str, int], list[dict[str, int]]]:
    """Project private transfers that matter to feed and MM attribution.

    Actor actions execute before market orders.  Unlike the older terminal
    helper, this projection handles PICKUP as well as DROP/PLACE and consumes
    WHEAT for legal FEED actions.  Harvested WHEAT is deliberately not credited
    to the feed reserve before execution, which keeps that reserve conservative.
    """
    private = get(obs, "private", {}) or {}
    shed = {
        str(item): max(0, int(quantity or 0))
        for item, quantity in dict(get(private, "shed", {}) or {}).items()
    }
    inventories = [
        {
            str(item): max(0, int(quantity or 0))
            for item, quantity in dict(inventory or {}).items()
        }
        for inventory in list(get(private, "inventories", []) or [])
    ]
    farm = _farm(obs)
    positions = [get(farm, "farmer", [0, 0]), *(get(farm, "hands", []) or [])]
    safe = _safe_action(action)
    actor_actions = [safe["farmer"], *safe["hands"]]
    while len(inventories) < len(positions):
        inventories.append({})
    tiles = list(get(farm, "tiles", []) or [])
    board_size = len(tiles) or 10
    access = _shed_access_tiles(board_size)
    animal_structures = {"COW": "PASTURE", "SHEEP": "PASTURE", "GOOSE": "COOP"}

    for index, unit_action in enumerate(actor_actions):
        if index >= len(positions) or index >= len(inventories):
            continue
        if not isinstance(unit_action, list) or not unit_action:
            continue
        position = positions[index]
        if not isinstance(position, (list, tuple)) or len(position) < 2:
            continue
        x, y = int(position[0]), int(position[1])
        if not (0 <= y < len(tiles) and 0 <= x < len(tiles[y])):
            continue
        tile = tiles[y][x]
        inventory = inventories[index]
        operation = str(unit_action[0])

        if operation == "DROP" and (x, y) in access:
            for item, quantity in list(inventory.items()):
                room = max(0, int(shed_capacity) - sum(shed.values()))
                deposited = min(max(0, int(quantity or 0)), room)
                if deposited:
                    shed[item] = shed.get(item, 0) + deposited
                # The official DROP discards overflow rather than retaining it.
                inventory.pop(item, None)
            continue

        if operation == "PICKUP" and (x, y) in access and len(unit_action) >= 2:
            item = str(unit_action[1])
            try:
                requested = int(unit_action[2]) if len(unit_action) >= 3 else 1
            except (TypeError, ValueError):
                requested = 0
            taken = _take(shed, item, max(0, requested))
            if taken:
                inventory[item] = inventory.get(item, 0) + taken
            continue

        if operation == "PLACE" and len(unit_action) >= 2:
            item = str(unit_action[1])
            structure = animal_structures.get(item)
            if (
                structure is not None
                and isinstance(tile, dict)
                and tile.get("kind") == structure
                and "animal" not in tile
            ):
                _take(inventory, item, 1)
                continue
            if (x, y) not in access:
                continue
            try:
                requested = int(unit_action[2]) if len(unit_action) >= 3 else 1
            except (TypeError, ValueError):
                requested = 0
            room = max(0, int(shed_capacity) - sum(shed.values()))
            deposited = _take(inventory, item, min(max(0, requested), room))
            if deposited:
                shed[item] = shed.get(item, 0) + deposited
            continue

        # Engine 1.32.7 resolves shed operations before checking ownership of
        # the standing tile.  Other tile-mutating operations, including FEED,
        # still no-op while the shed-access tile itself is locked.
        if tile == "LOCKED":
            continue

        if (
            operation == "FEED"
            and isinstance(tile, dict)
            and "animal" in tile
            and not bool(tile.get("fed_today", False))
        ):
            _take(inventory, "WHEAT", 1)

    return shed, inventories


def _fib(index: int) -> int:
    a, b = 1, 1
    for _ in range(max(0, int(index))):
        a, b = b, a + b
    return a


def _order_cost(
    order: list,
    *,
    item_price: float,
    hires_today: int,
    unlocked_quadrants: int,
    hire_multiplier: int,
) -> tuple[float, int, int]:
    """Conservative cost and updated HIRE/LAND counters for one order."""
    if not order:
        return 0.0, hires_today, unlocked_quadrants
    operation = str(order[0])
    if operation == "HIRE":
        return (
            float(max(1, int(hire_multiplier)) * _fib(hires_today)),
            hires_today + 1,
            unlocked_quadrants,
        )
    if operation == "BUY_LAND":
        extra = max(0, unlocked_quadrants - 1)
        cost = LAND_COST[extra] if extra < len(LAND_COST) else 0
        return float(cost), hires_today, unlocked_quadrants + (cost > 0)
    if len(order) < 3:
        return 0.0, hires_today, unlocked_quadrants
    try:
        quantity = max(0, int(order[2]))
    except (TypeError, ValueError):
        quantity = 0
    item = str(order[1])
    if operation == "BUY_SEED":
        cost = CROP_COST.get(item, 0) * quantity
    elif operation == "BUY_ANIMAL":
        cost = ANIMAL_COST.get(item, 0) * quantity
    elif operation == "BUY_PRODUCT":
        cost = max(1.0, float(item_price)) * quantity
    else:
        cost = 0.0
    return float(cost), hires_today, unlocked_quadrants


def planned_investment_cost(
    obs: Any,
    actions: list[dict],
    *,
    start_step: int,
    horizon: int,
    item_price: float,
    hire_multiplier: int = 1,
) -> float:
    """Reserve route costs over a short hold/exit window without sale credit."""
    farm = _farm(obs)
    current_day = int(get(obs, "day", start_step // 24) or 0)
    hires_today = int(get(farm, "hires_today", 0) or 0)
    quadrants = len(get(farm, "unlocked_quadrants", []) or [])
    total = 0.0
    last_day = current_day
    stop = min(len(actions), start_step + max(0, int(horizon)))
    for step in range(max(0, int(start_step)), stop):
        day = step // 24
        if day != last_day:
            hires_today = 0
            last_day = day
        action = actions[step] if step < len(actions) else {}
        for order in (action or {}).get("market", []) or []:
            cost, hires_today, quadrants = _order_cost(
                list(order),
                item_price=item_price,
                hires_today=hires_today,
                unlocked_quadrants=quadrants,
                hire_multiplier=hire_multiplier,
            )
            total += cost
    return total


def reserve_breakdown(
    obs: Any,
    actions: list[dict],
    configuration: Any,
    config: MarketMakerConfig,
    current_action: Any | None = None,
) -> ReserveBreakdown:
    farm = _farm(obs)
    money = float(get(farm, "money", 0) or 0)
    step = int(get(obs, "step", 0) or 0)
    market = get(obs, "market", {}) or {}
    inventory = get(market, "inventory", {}) or {}
    item_inventory = int(get(inventory, config.item, 10000) or 10000)
    current_quote = float(market_price(config.item, item_inventory))
    feed_item = str(config.feed_item or "WHEAT")
    feed_inventory = int(get(inventory, feed_item, 10000) or 10000)
    feed_quote = float(market_price(feed_item, feed_inventory))

    action = (
        current_action
        if current_action is not None
        else actions[step] if 0 <= step < len(actions) else {}
    )
    official_shed_capacity = int(
        get(configuration, "shedCapacity", config.shed_capacity)
        or config.shed_capacity
    )
    effective_shed_capacity = min(
        int(config.shed_capacity), max(1, official_shed_capacity)
    )
    projected_shed, projected_inventories = _project_private_after_actor(
        obs,
        action,
        shed_capacity=effective_shed_capacity,
    )
    projected_wheat = max(
        0, int(projected_shed.get(feed_item, 0) or 0)
    ) + sum(
        max(0, int(inventory.get(feed_item, 0) or 0))
        for inventory in projected_inventories
    )
    # Existing SELL commitments reduce protected stock.  Existing BUY orders
    # are not credited until they execute, so their failure cannot weaken the
    # feed reserve.
    for raw in (_safe_action(action).get("market", []) or []):
        order = list(raw or [])
        if len(order) < 3 or str(order[1]) != feed_item or order[0] != "SELL":
            continue
        try:
            projected_wheat = max(0, projected_wheat - max(0, int(order[2])))
        except (TypeError, ValueError):
            continue

    required_feed = int(
        math.ceil(_animal_count(farm) * max(0.0, config.feed_days_reserve))
    )
    feed_deficit = max(0, required_feed - projected_wheat)
    if feed_deficit:
        feed_cost, _ = execute_buy(feed_item, feed_inventory, feed_deficit)
    else:
        feed_cost = 0
    feed = float(feed_cost) * max(1.0, float(config.price_cost_buffer))

    investment = planned_investment_cost(
        obs,
        actions,
        start_step=step,
        horizon=max(1, int(config.investment_horizon)),
        item_price=feed_quote,
        hire_multiplier=int(get(configuration, "farmHandCostMult", 1) or 1),
    ) * max(1.0, float(config.price_cost_buffer))
    available = max(
        0.0,
        money - float(config.minimum_cash_reserve) - feed - investment,
    )
    return ReserveBreakdown(
        money=money,
        cash_floor=float(config.minimum_cash_reserve),
        feed=feed,
        investment=investment,
        available=available,
    )


def _shed_after_market(
    projected: dict[str, int],
    market: Iterable[list],
    *,
    shed_capacity: int,
) -> dict[str, int]:
    """Conservative unilateral shed projection for capacity accounting."""
    shed = {str(item): max(0, int(quantity or 0)) for item, quantity in projected.items()}
    for raw in market:
        order = list(raw or [])
        if len(order) < 3:
            continue
        operation, item = str(order[0]), str(order[1])
        try:
            quantity = max(0, int(order[2]))
        except (TypeError, ValueError):
            quantity = 0
        if operation == "SELL":
            shed[item] = max(0, shed.get(item, 0) - quantity)
        elif operation in ("BUY_PRODUCT", "BUY_ANIMAL"):
            room = max(0, int(shed_capacity) - sum(shed.values()))
            shed[item] = shed.get(item, 0) + min(quantity, room)
    return shed


def _wheat_after_market(quantity: int, market: Iterable[list], item: str) -> int:
    quantity = max(0, int(quantity))
    for raw in market:
        order = list(raw or [])
        if len(order) < 3 or str(order[1]) != item:
            continue
        try:
            units = max(0, int(order[2]))
        except (TypeError, ValueError):
            units = 0
        if order[0] == "SELL":
            quantity = max(0, quantity - units)
        elif order[0] == "BUY_PRODUCT":
            quantity += units
    return quantity


def _inventory_after_wheat_orders(
    inventory: int, market: Iterable[list], item: str
) -> int:
    inventory = int(inventory)
    for raw in market:
        order = list(raw or [])
        if len(order) < 3 or str(order[1]) != item:
            continue
        try:
            units = max(0, int(order[2]))
        except (TypeError, ValueError):
            units = 0
        if order[0] == "SELL":
            _revenue, inventory = execute_sell(item, inventory, units)
        elif order[0] == "BUY_PRODUCT":
            _cost, inventory = execute_buy(item, inventory, units)
    return inventory


class MarketMakerExpert:
    """Stateful expert that owns only its incremental market position."""

    def __init__(self, actions: list[dict], config: MarketMakerConfig | None = None):
        self.actions = copy.deepcopy(actions)
        self.config = config or MarketMakerConfig()
        self.states = {0: {}, 1: {}}
        self.telemetry = {
            "games": 0,
            "entries": 0,
            "entry_units": 0,
            "exits": 0,
            "exit_units": 0,
            "position_consumed_units": 0,
            "expected_profit": 0.0,
            "cash_blocks": 0,
            "capacity_blocks": 0,
            "slot_blocks": 0,
            "edge_blocks": 0,
            "deferred_exits": 0,
            "mirror_latches": 0,
            "mirror_entries": 0,
            "deployed_cash": 0.0,
            "maximum_feed_reserve": 0.0,
            "maximum_investment_reserve": 0.0,
            "minimum_entry_headroom": None,
        }

    def _reset(self, seat: int, step: int) -> dict:
        state = {
            "last_step": step,
            "open_units": 0,
            "entry_step": -1,
            "baseline_wheat": 0,
            "near_streak": 0,
            "mirror_mode": None,
        }
        self.states[seat] = state
        self.telemetry["games"] += 1
        return state

    def _future_has_exit_slot(self, step: int, max_orders: int) -> bool:
        exit_step = step + 1
        if exit_step >= len(self.actions):
            return False
        market = (self.actions[exit_step] or {}).get("market", []) or []
        return len(market) < int(max_orders)

    def _exit(
        self,
        obs: Any,
        action: dict,
        state: dict,
        configuration: Any,
    ) -> dict:
        market = list(action.get("market", []) or [])
        max_orders = min(
            int(self.config.max_orders),
            max(
                1,
                int(
                    get(
                        configuration,
                        "maxMarketOrdersPerTurn",
                        self.config.max_orders,
                    )
                    or self.config.max_orders
                ),
            ),
        )
        if len(market) >= max_orders:
            self.telemetry["slot_blocks"] += 1
            self.telemetry["deferred_exits"] += 1
            return action
        private = get(obs, "private", {}) or {}
        shed = get(private, "shed", {}) or {}
        observed_wheat = max(0, int(get(shed, self.config.item, 0) or 0))
        official_shed_capacity = int(
            get(configuration, "shedCapacity", self.config.shed_capacity)
            or self.config.shed_capacity
        )
        effective_shed_capacity = min(
            int(self.config.shed_capacity), max(1, official_shed_capacity)
        )
        projected, _inventories = _project_private_after_actor(
            obs,
            action,
            shed_capacity=effective_shed_capacity,
        )
        projected_wheat = max(0, int(projected.get(self.config.item, 0) or 0))
        actor_delta = projected_wheat - observed_wheat
        operational = max(0, int(state.get("baseline_wheat", 0)) + actor_delta)
        operational = _wheat_after_market(operational, market, self.config.item)
        total = _wheat_after_market(projected_wheat, market, self.config.item)
        available_position = max(0, total - operational)
        open_units = max(0, int(state.get("open_units", 0)))
        quantity = min(open_units, available_position)
        consumed = max(0, open_units - quantity)
        if consumed:
            # Actor actions execute before the market.  If part of the
            # incremental position was picked up or otherwise consumed, it is
            # no longer an open market position and must not block future
            # entries.  The operational route owns those units from here.
            self.telemetry["position_consumed_units"] += consumed
        if quantity <= 0:
            state["open_units"] = 0
            state["baseline_wheat"] = operational
            return action
        market.append(["SELL", self.config.item, quantity])
        action["market"] = market
        state["open_units"] = 0
        state["baseline_wheat"] = operational
        self.telemetry["exits"] += 1
        self.telemetry["exit_units"] += quantity
        return action

    def _entry(self, obs: Any, action: dict, configuration: Any, state: dict) -> dict:
        step = int(get(obs, "step", 0) or 0)
        if not (
            self.config.enabled
            and int(self.config.start_step) <= step <= int(self.config.stop_entry_step)
        ):
            return action
        demand = demand_on_step(obs, configuration, self.config.item)
        if demand <= 0:
            return action
        market_orders = list(action.get("market", []) or [])
        max_orders = min(
            int(self.config.max_orders),
            max(
                1,
                int(
                    get(
                        configuration,
                        "maxMarketOrdersPerTurn",
                        self.config.max_orders,
                    )
                    or self.config.max_orders
                ),
            ),
        )
        if len(market_orders) >= max_orders or not self._future_has_exit_slot(
            step, max_orders
        ):
            self.telemetry["slot_blocks"] += 1
            return action

        official_shed_capacity = int(
            get(configuration, "shedCapacity", self.config.shed_capacity)
            or self.config.shed_capacity
        )
        effective_shed_capacity = min(
            int(self.config.shed_capacity), max(1, official_shed_capacity)
        )
        projected, _inventories = _project_private_after_actor(
            obs,
            action,
            shed_capacity=effective_shed_capacity,
        )
        after_base = _shed_after_market(
            projected,
            market_orders,
            shed_capacity=effective_shed_capacity,
        )
        capacity = max(
            0,
            effective_shed_capacity
            - int(self.config.shed_headroom)
            - sum(after_base.values()),
        )
        if capacity <= 0:
            self.telemetry["capacity_blocks"] += 1
            return action

        reserve = reserve_breakdown(
            obs,
            self.actions,
            configuration,
            self.config,
            current_action=action,
        )
        if reserve.available <= 0:
            self.telemetry["cash_blocks"] += 1
            return action

        market = get(obs, "market", {}) or {}
        inventories = get(market, "inventory", {}) or {}
        inventory = int(get(inventories, self.config.item, 10000) or 10000)
        inventory = _inventory_after_wheat_orders(
            inventory, market_orders, self.config.item
        )
        maximum = min(int(self.config.max_batch), capacity)
        affordable = 0
        for quantity in range(1, maximum + 1):
            cost, _ = execute_buy(self.config.item, inventory, quantity)
            if cost * max(1.0, float(self.config.price_cost_buffer)) > reserve.available:
                break
            affordable = quantity
        if affordable <= 0:
            self.telemetry["cash_blocks"] += 1
            return action

        threshold = (
            float(self.config.mirror_minimum_expected_profit)
            if state.get("mirror_mode")
            else float(self.config.minimum_expected_profit)
        )
        plan = best_round_trip_quantity(
            item=self.config.item,
            inventory=inventory,
            intervening_demand=demand,
            maximum_quantity=affordable,
            minimum_expected_profit=threshold,
        )
        if plan is None:
            self.telemetry["edge_blocks"] += 1
            return action

        market_orders.append(["BUY_PRODUCT", self.config.item, plan.quantity])
        action["market"] = market_orders
        state["open_units"] = plan.quantity
        state["entry_step"] = step
        state["baseline_wheat"] = _wheat_after_market(
            max(0, int(projected.get(self.config.item, 0) or 0)),
            market_orders[:-1],
            self.config.item,
        )
        self.telemetry["entries"] += 1
        if state.get("mirror_mode"):
            self.telemetry["mirror_entries"] += 1
        self.telemetry["entry_units"] += plan.quantity
        self.telemetry["expected_profit"] += plan.expected_profit
        self.telemetry["deployed_cash"] += plan.buy_cost
        self.telemetry["maximum_feed_reserve"] = max(
            float(self.telemetry["maximum_feed_reserve"]), reserve.feed
        )
        self.telemetry["maximum_investment_reserve"] = max(
            float(self.telemetry["maximum_investment_reserve"]),
            reserve.investment,
        )
        headroom = reserve.available - (
            plan.buy_cost * max(1.0, float(self.config.price_cost_buffer))
        )
        prior_headroom = self.telemetry["minimum_entry_headroom"]
        self.telemetry["minimum_entry_headroom"] = (
            headroom
            if prior_headroom is None
            else min(float(prior_headroom), headroom)
        )
        return action

    def apply(self, obs: Any, action: Any, configuration: Any = None) -> dict:
        result = _safe_action(action)
        seat = _seat(obs)
        step = int(get(obs, "step", 0) or 0)
        state = self.states[seat]
        if step == 0 or step < int(state.get("last_step", -1)):
            state = self._reset(seat, step)
        state["last_step"] = step
        distance = clone_distance(obs)
        if distance <= float(self.config.mirror_distance_threshold):
            state["near_streak"] = int(state.get("near_streak", 0)) + 1
        else:
            state["near_streak"] = 0
        if state.get("mirror_mode") is None and step >= int(self.config.start_step):
            state["mirror_mode"] = (
                int(state.get("near_streak", 0))
                >= int(self.config.mirror_streak_required)
            )
            if state["mirror_mode"]:
                self.telemetry["mirror_latches"] += 1

        if int(state.get("open_units", 0)) > 0:
            result = self._exit(obs, result, state, configuration)
            if int(state.get("open_units", 0)) > 0:
                age = step - int(state.get("entry_step", step))
                if age >= int(self.config.max_hold_steps):
                    self.telemetry["deferred_exits"] += 1
                return result
            # Do not immediately re-enter on the same turn as an exit.
            return result
        return self._entry(obs, result, configuration, state)


def wrap_market_maker(base_policy, actions, config: MarketMakerConfig | None = None):
    expert = MarketMakerExpert(actions, config)

    def policy(obs, configuration=None):
        return expert.apply(obs, base_policy(obs, configuration), configuration)

    policy.expert = expert
    policy.telemetry = expert.telemetry
    policy.config = expert.config
    return policy
